if(empty($_SESSION['ag_page_designer_csrf'])) $_SESSION['ag_page_designer_csrf']=bin2hex(random_bytes(32));
$csrf=$_SESSION['ag_page_designer_csrf'];
function pd_response($data,$status=200) { http_response_code($status); header('Content-Type: application/json; charset=utf-8'); echo json_encode($data,JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE); exit; }
if(($_SERVER['REQUEST_METHOD'] ?? 'GET')==='POST') {
    try {
        if(!isset($_POST['csrf']) || !is_string($_POST['csrf']) || !hash_equals($csrf,$_POST['csrf'])) throw new RuntimeException('Security token expired or request exceeds the server upload limit. Reload and retry.');
        $action=$_POST['action'] ?? ''; $revision=$_POST['revision'] ?? '';
        $result=function($p){return array('ok'=>true,'page'=>$p,'revision'=>ag_pd_editor_revision($p['id']),'publishing'=>ag_pd_publishing_state($p['id']),'pages'=>ag_pd_editor_pages(),'menuPages'=>ag_pd_menu_pages());};
        if($action==='form_inbox')pd_response(array('ok'=>true,'inbox'=>ag_pf_inbox(!empty($_POST['archived']),$_POST['offset'] ?? 0)));
        if($action==='form_message'){ag_pf_message_action($_POST['messageId'] ?? '',$_POST['operation'] ?? '');pd_response(array('ok'=>true));}
        if($action==='site_inventory')pd_response(array('ok'=>true,'inventory'=>ag_ps_inventory()));
        if($action==='site_replace_preview')pd_response(array('ok'=>true,'preview'=>ag_ps_preview(json_decode($_POST['spec'] ?? '',true))));
        if($action==='site_replace_apply'){ $res=ag_ps_apply(json_decode($_POST['spec'] ?? '',true),json_decode($_POST['expected'] ?? '',true));$current=ag_pd_edit_page($_POST['currentId'] ?? '');if($current)pd_response($result($current)+array('result'=>$res));pd_response(array('ok'=>true,'result'=>$res,'pages'=>ag_pd_editor_pages())); }
        if($action==='site_scan')pd_response(array('ok'=>true,'scan'=>ag_ps_scan($_POST['scope'] ?? 'drafts',$_SERVER['HTTP_HOST'] ?? '')));
        if($action==='template_upload') pd_response(array('ok'=>true,'import'=>ag_ti_upload($_FILES['templateZip'] ?? null)));
        if($action==='template_preview') pd_response(array('ok'=>true,'preview'=>ag_ti_preview($_POST['importToken'] ?? '',$_POST['htmlFile'] ?? '')));
        if($action==='template_import') pd_response($result(ag_ti_commit($_POST['importToken'] ?? '',$_POST['htmlFile'] ?? '',($_POST['reviewed'] ?? '')==='1')));
        if($action==='template_discard'){ag_ti_discard($_POST['importToken'] ?? '');pd_response(array('ok'=>true));}
        if($action==='library_list') pd_response(array('ok'=>true,'items'=>ag_pbl_summary($_POST['kind'] ?? '',!empty($_POST['archived']))));
        if($action==='library_get') pd_response(array('ok'=>true,'entry'=>ag_pbl_download($_POST['kind'] ?? '',$_POST['itemId'] ?? '')));
        if($action==='library_preview') pd_response(array('ok'=>true,'html'=>ag_pbl_preview($_POST['kind'] ?? '',$_POST['itemId'] ?? '',json_decode($_POST['theme'] ?? '{}',true))));
        if($action==='library_save') pd_response(array('ok'=>true,'entry'=>ag_pbl_capture($_POST['kind'] ?? '',json_decode($_POST['page'] ?? '',true),$_FILES,$_POST['nodeId'] ?? '',$_POST['name'] ?? '',$revision)));
        if($action==='library_edit') pd_response(array('ok'=>true,'entry'=>ag_pbl_edit($_POST['kind'] ?? '',$_POST['itemId'] ?? '',$_POST['itemRevision'] ?? '',$_POST['operation'] ?? '',$_POST['name'] ?? '')));
        if($action==='media_list') { $archived=ag_pbl_list('media',true);foreach($archived as &$entry)$entry['revision']=ag_pd_revision($entry);unset($entry);pd_response(array('ok'=>true,'items'=>ag_pbl_media_list(),'archived'=>$archived)); }
        if($action==='media_add') pd_response(array('ok'=>true,'entry'=>ag_pbl_media_add($_FILES['image'] ?? null,$_POST['sourceId'] ?? '',$_POST['file'] ?? '',$_POST['name'] ?? '')));
        if(in_array($action,array('site_get','site_save','site_publish'),true)) {
            if($action!=='site_get') ag_pbl_site_save(json_decode($_POST['site'] ?? '',true),$_POST['siteRevision'] ?? '',$action==='site_publish');
            pd_response(array('ok'=>true,'site'=>ag_pbl_site_edit(),'live'=>ag_pbl_site_live(),'siteRevision'=>ag_pbl_site_revision(),'hasDraft'=>is_file(ag_pd_root().'/site-draft.json'),'sections'=>ag_pbl_summary('section'),'pages'=>ag_pd_editor_pages()));
        }
        if($action==='site_preview') pd_response(array('ok'=>true,'html'=>ag_pbl_site_preview(json_decode($_POST['site'] ?? '',true))));
        if($action==='import') pd_response($result(ag_pd_import_upload($_FILES['package'] ?? null)));
        $id=$_POST['id'] ?? '';
        if($action==='history') pd_response(array('ok'=>true,'items'=>ag_pd_history_list($id)));
        if($action==='revision') { if(!ag_pd_edit_page($id)) throw new RuntimeException('Page not found.'); $e=ag_pd_history_entry($id,$_POST['token'] ?? ''); pd_response(array('ok'=>true,'html'=>ag_pd_render($e['page'],true))); }
        if($action==='restore') pd_response($result(ag_pd_restore_revision($id,$_POST['token'] ?? '',$revision)));
        if($action==='offline') pd_response($result(ag_pd_take_offline($id,$revision)));
        if($action==='export') pd_response(array('ok'=>true,'package'=>ag_pd_export_package($id,$revision)));
        if($action==='delete') {
            ag_pd_lock(function() use($revision) { $p=ag_pd_edit_page($_POST['id'] ?? ''); if(!$p || !hash_equals(ag_pd_editor_revision($p['id']),(string)$revision)) throw new RuntimeException('Page changed or no longer exists. Reload before deleting.'); ag_pd_delete_page($p); });
            pd_response(array('ok'=>true,'menuPages'=>ag_pd_menu_pages()));
        }
        if($action==='publish_check') pd_response(array('ok'=>true,'report'=>ag_pc_check(json_decode($_POST['page'] ?? '',true),json_decode($_POST['pending'] ?? '[]',true),$_SERVER['HTTP_HOST'] ?? '')));
        $input=json_decode($_POST['page'] ?? '',true); if(!is_array($input)) throw new RuntimeException('Invalid page data.');
