        if(!in_array($action,array('save','publish'),true)) throw new RuntimeException('Unknown action.');
        $p=ag_pd_commit($input,$_FILES,$revision,$action==='publish'?'publish':'draft');
        pd_response($result($p));
    } catch(Throwable $e) { pd_response(array('ok'=>false,'error'=>$e->getMessage()),400); }
}
