try { $pages=ag_pd_editor_pages(); if(!empty($_GET['id'])) { $raw=ag_pd_edit_page($_GET['id']); if(!$raw) throw new RuntimeException('Page not found.'); } } catch(Throwable $e) { $error=$e->getMessage(); }
$p=$raw ? ag_pd_normalize($raw) : ag_pd_default_page();
function pd_ini_bytes($value) { $value=trim($value); $n=(float)$value; $unit=strtolower(substr($value,-1)); return (int)($n*($unit==='g'?1073741824:($unit==='m'?1048576:($unit==='k'?1024:1)))); }
